import{_ as p,a0 as i,w as g,s as u,I as o,x as n,a1 as e,A as r,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"11 個使用 GNOME 3 桌面環境的理由 | LCTT x X-CMD","titleTemplate":false,"description":"11 個使用 GNOME 3 桌面環境的理由 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"11 個使用 GNOME 3 桌面環境的理由 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"11 個使用 GNOME 3 桌面環境的理由 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170529 11 reasons to use the GNOME 3 desktop environment for Linux","title":"11 個使用 GNOME 3 桌面環境的理由","tag":"201708","desc":""},"relativePath":"201708/20170529 11 reasons to use the GNOME 3 desktop environment for Linux.md","filePath":"[post].md"}'),d={name:"201708/20170529 11 reasons to use the GNOME 3 desktop environment for Linux.md"};function m(a,t,f,N,M,E){const s=i("Link");return g(),u("div",null,[t[32]||(t[32]=o("h1",{id:"_11-個使用-gnome-3-桌面環境的理由",tabindex:"-1"},[n("11 個使用 GNOME 3 桌面環境的理由 "),o("a",{class:"header-anchor",href:"#_11-個使用-gnome-3-桌面環境的理由","aria-label":"Permalink to “11 個使用 GNOME 3 桌面環境的理由”"},"​")],-1)),t[33]||(t[33]=o("blockquote",null,[o("p",null,"GNOME 3 桌面的設計目的是簡單、易於訪問和可靠。GNOME 的受歡迎程度證明達成了這些目標。")],-1)),t[34]||(t[34]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/custom_gnomes.png?itok=iG98iL8d",alt:"11 reasons to use the GNOME desktop environment",title:"11 reasons to use the GNOME desktop environment"})],-1)),o("p",null,[t[1]||(t[1]=n("去年年底，在我升級到 Fedora 25 後，新版本 ",-1)),e(s,{href:"https://opensource.com/life/15/4/9-reasons-to-use-kde"},{default:r(()=>[...t[0]||(t[0]=[n("KDE",-1)])]),_:1}),t[2]||(t[2]=n(" Plasma 出現了一些問題，這使我難以完成任何工作。所以我決定嘗試其他的 Linux 桌面環境有兩個原因。首先，我需要完成我的工作。第二，多年來一直使用 KDE，我想可能是嘗試一些不同的桌面的時候了。",-1))]),o("p",null,[t[6]||(t[6]=n("我嘗試了幾個星期的第一個替代桌面是我在 1 月份文章中寫到的 ",-1)),e(s,{href:"https://linux.cn/article-8606-1.html"},{default:r(()=>[...t[3]||(t[3]=[n("Cinnamon",-1)])]),_:1}),t[7]||(t[7]=n("，然後我寫了用了大約八個星期的",-1)),e(s,{href:"https://linux.cn/article-8434-1.html"},{default:r(()=>[...t[4]||(t[4]=[n("LXDE",-1)])]),_:1}),t[8]||(t[8]=n("，我發現這裏有很多事情我都喜歡。我用了 ",-1)),e(s,{href:"https://www.gnome.org/gnome-3/"},{default:r(()=>[...t[5]||(t[5]=[n("GNOME 3",-1)])]),_:1}),t[9]||(t[9]=n(" 幾個星期來寫了這篇文章。",-1))]),t[35]||(t[35]=l('<p>像幾乎所有的網絡世界一樣，GNOME 是縮寫；它代表 “GNU 網絡對象模型”（GNU Network Object Model）。GNOME 3 桌面設計的目的是簡單、易於訪問和可靠。GNOME 的受歡迎程度證明達成了這些目標。</p><p>GNOME 3 在需要大量屏幕空間的環境中非常有用。這意味着兩個具有高分辨率的大屏幕，並最大限度地減少桌面小部件、面板和用來啓動新程序之類任務的圖標所需的空間。GNOME 項目有一套人機接口指南（HIG），用來定義人類應該如何與計算機交互的 GNOME 哲學。</p><h3 id="我使用-gnome-3-的十一個原因" tabindex="-1">我使用 GNOME 3 的十一個原因 <a class="header-anchor" href="#我使用-gnome-3-的十一個原因" aria-label="Permalink to “我使用 GNOME 3 的十一個原因”">​</a></h3><p>1、 <strong>諸多選擇：</strong> GNOME 以多種形式出現在我個人喜愛的 Fedora 等一些發行版上。你可以選擇的桌面登錄選項有 GNOME Classic、Xorg 上的 GNOME、GNOME 和 GNOME（Wayland）。從表面上看，啓動後這些都是一樣的，但它們使用不同的 X 服務器，或者使用不同的工具包構建。Wayland 在小細節上提供了更多的功能，例如動態滾動，拖放和中鍵粘貼。</p><p>2、 <strong>入門教程：</strong> 在用户第一次登錄時會顯示入門教程。它向你展示瞭如何執行常見任務，並提供了大量的幫助鏈接。教程在首次啓動後關閉後也可輕鬆訪問，以便隨時訪問該教程。教程非常簡單直觀，這為 GNOME 新用户提供了一個簡單明瞭開始。要之後返回本教程，請點擊 <strong>Activities</strong>，然後點擊會顯示程序的有九個點的正方形。然後找到並點擊標為救生員圖標的 <strong>Help</strong>。</p><p>3、 <strong>桌面整潔：</strong> 對桌面環境採用極簡方法以減少雜亂，GNOME 設計為僅提供具備可用環境所必需的最低限度。你應該只能看到頂部欄（是的，它就叫這個），其他所有的都被隱藏，直到需要才顯示。目的是允許用户專注於手頭的任務，並儘量減少桌面上其他東西造成的干擾。</p><p>4、 <strong>頂部欄：</strong> 無論你想做什麼，頂部欄總是開始的地方。你可以啓動應用程序、註銷、關閉電源、啓動或停止網絡等。不管你想做什麼都很簡單。除了當前應用程序之外，頂欄通常是桌面上唯一的其他對象。</p><p>5、 <strong>dash：</strong> 如下所示，在默認情況下, dash 包含三個圖標。在開始使用應用程序時，會將它們添加到 dash 中，以便在其中顯示最常用的應用程序。你也可以從應用程序查看器中將應用程序圖標添加到 dash 中。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/gnome_fig_2.png" alt="gnome_fig_2.png"></p><p>6、 <strong>應用程序瀏覽器：</strong> 我真的很喜歡這個可以從位於 GNOME 桌面左側的垂直條上訪問應用程序瀏覽器。除非有一個正在運行的程序，GNOME 桌面通常沒有任何東西，所以你必須點擊頂部欄上的 <strong>Activities</strong> 選區，點擊 dash 底部的九個點組成的正方形，它是應用程序瀏覽器的圖標。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/gnome_fig_1.png" alt="gnome_fig_1.png"></p><p>如上所示，瀏覽器本身是一個由已安裝的應用程序的圖標組成的矩陣。矩陣下方有一對互斥的按鈕，<strong>Frequent</strong> 和 <strong>All</strong>。默認情況下，應用程序瀏覽器會顯示所有安裝的應用。點擊 <strong>Frequent</strong> 按鈕，它會只顯示最常用的應用程序。向上和向下滾動以找到要啓動的應用程序。應用程序按名稱按字母順序顯示。</p>',12)),o("p",null,[e(s,{href:"https://www.gnome.org/gnome-3/"},{default:r(()=>[...t[10]||(t[10]=[n("GNOME",-1)])]),_:1}),t[11]||(t[11]=n(" 官網和內置的幫助有更多關於瀏覽器的細節。",-1))]),t[36]||(t[36]=l('<p>7、 <strong>應用程序就緒通知：</strong> 當新啓動的應用程序的窗口打開並準備就緒時，GNOME 會在屏幕頂部顯示一個整齊的通知。只需點擊通知即可切換到該窗口。與在其他桌面上搜索新打開的應用程序窗口相比，這節省了一些時間。</p><p>8、 <strong>應用程序顯示：</strong> 為了訪問不可見的其它運行的應用程序，點擊 <strong>Activities</strong> 菜單。這將在桌面上的矩陣中顯示所有正在運行的應用程序。點擊所需的應用程序將其帶到前台。雖然當前應用程序顯示在頂欄中，但其他正在運行的應用程序不會。</p><p>9、 <strong>最小的窗口裝飾：</strong> 桌面上打開窗口也很簡單。標題欄上唯一顯示的按鈕是關閉窗口的 “X”。所有其他功能，如最小化、最大化、移動到另一個桌面等，可以通過在標題欄上右鍵單擊來訪問。</p><p>10、 <strong>自動創建的新桌面：</strong> 在使用下一空桌面的時候將自動創建的新的空桌面。這意味着總是有一個空的桌面在需要時可以使用。我使用的所有其他的桌面系統都可以讓你在桌面活動時設置桌面數量，但必須使用系統設置手動完成。</p><p>11、 <strong>兼容性：</strong> 與我所使用的所有其他桌面一樣，為其他桌面創建的應用程序可在 GNOME 上正常工作。這功能讓我有可能測試這些桌面，以便我可以寫出它們。</p><h3 id="最後的思考" tabindex="-1">最後的思考 <a class="header-anchor" href="#最後的思考" aria-label="Permalink to “最後的思考”">​</a></h3><p>GNOME 不像我以前用過的桌面。它的主要指導是“簡單”。其他一切都要以簡單易用為前提。如果你從入門教程開始，學習如何使用 GNOME 需要很少的時間。這並不意味着 GNOME 有所不足。它是一款始終保持不變的功能強大且靈活的桌面。</p>',7)),o("p",null,[t[15]||(t[15]=n("（題圖：",-1)),e(s,{href:"https://pixabay.com/en/users/karpartenhund-3077375/"},{default:r(()=>[...t[12]||(t[12]=[n("Gunnar Wortmann",-1)])]),_:1}),t[16]||(t[16]=n(" 通過 ",-1)),e(s,{href:"https://pixabay.com/en/garden-gnome-black-and-white-f%C3%B6hr-1584401/"},{default:r(()=>[...t[13]||(t[13]=[n("Pixabay",-1)])]),_:1}),t[17]||(t[17]=n("。由 Opensource.com 修改。",-1)),e(s,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:r(()=>[...t[14]||(t[14]=[n("CC BY-SA 4.0",-1)])]),_:1}),t[18]||(t[18]=n("）",-1))]),t[37]||(t[37]=o("hr",null,null,-1)),t[38]||(t[38]=o("p",null,"作者簡介：",-1)),t[39]||(t[39]=o("p",null,"David Both - David Both 是位於北卡羅來納州羅利的 Linux 和開源倡導者。他已經在 IT 行業工作了四十多年，併為 IBM 教授 OS/2 超過 20 年。在 IBM，他在 1981 年為初始的 IBM PC 寫了第一個培訓課程。他為紅帽教授 RHCE 課程，曾在 MCI Worldcom、思科和北卡羅來納州工作。他一直在使用 Linux 和開源軟件近 20 年。",-1)),t[40]||(t[40]=o("hr",null,null,-1)),o("p",null,[t[20]||(t[20]=n("via: ",-1)),e(s,{href:"https://opensource.com/article/17/5/reasons-gnome"},{default:r(()=>[...t[19]||(t[19]=[n("https://opensource.com/article/17/5/reasons-gnome",-1)])]),_:1})]),o("p",null,[t[24]||(t[24]=n("作者：",-1)),e(s,{href:"https://opensource.com/users/dboth"},{default:r(()=>[...t[21]||(t[21]=[n("David Both",-1)])]),_:1}),t[25]||(t[25]=n(" 譯者：",-1)),e(s,{href:"https://github.com/geekpi"},{default:r(()=>[...t[22]||(t[22]=[n("geekpi",-1)])]),_:1}),t[26]||(t[26]=n(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:r(()=>[...t[23]||(t[23]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[29]||(t[29]=n("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[27]||(t[27]=[n("LCTT",-1)])]),_:1}),t[30]||(t[30]=n(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:r(()=>[...t[28]||(t[28]=[n("Linux中國",-1)])]),_:1}),t[31]||(t[31]=n(" 榮譽推出",-1))])])}const x=p(d,[["render",m]]);export{T as __pageData,x as default};
